<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Atur Ulang Kata Sandi</title><style>body{font-family:Arial,sans-serif;background:#171717;display:grid;place-items:center;min-height:100vh;margin:0}.box{background:#fff;padding:32px;border-radius:16px;width:min(420px,90%)}label{display:grid;gap:8px;margin:18px 0;font-weight:700}input{padding:12px;border:1px solid #ddd;border-radius:8px;font:inherit}.button{width:100%;padding:13px;border:0;border-radius:8px;background:#171717;color:#fff;font-weight:700}.password{display:flex;gap:8px}.password input{flex:1}.password button{border:1px solid #ddd;background:#fff;border-radius:8px}</style></head><body><main class="box"><h1>Atur ulang kata sandi</h1><form method="POST" action="{{ route('password.update') }}">@csrf<input type="hidden" name="token" value="{{ $token }}"><label>Email<input type="email" name="email" value="{{ $email }}" required></label><label>Kata sandi baru<div class="password"><input id="password" type="password" name="password" required><button type="button" onclick="password.type=password.type==='password'?'text':'password'">Lihat</button></div></label><label>Konfirmasi kata sandi<input type="password" name="password_confirmation" required></label><button class="button" type="submit">Simpan kata sandi</button></form></main></body></html>
